CREATE OR REPLACE FUNCTION public.admin_end_bus_route_service(p_assignment_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_ids uuid[] := coalesce(p_assignment_ids, array[]::uuid[]);
  v_driver_count integer;
  v_student_count integer;
begin
  if auth.uid() is null
    or v_tenant_id is null
    or not safebus_private.is_transportation_write_admin() then
    raise exception 'Admin tenant context is required.' using errcode = '42501';
  end if;
  if cardinality(v_ids) = 0
    or (select count(*) from public.bus_route_assignments bra
        where bra.id = any(v_ids) and bra.tenant_id = v_tenant_id) <> cardinality(v_ids) then
    raise exception 'Route service assignments were not found.' using errcode = 'P0002';
  end if;

  perform 1 from public.bus_route_assignments bra where bra.id = any(v_ids) for update;
  if exists (
    select 1
    from public.driver_trips dt
    join public.bus_route_assignments bra
      on bra.id = any(v_ids)
      and bra.tenant_id = dt.tenant_id
      and bra.bus_id = dt.bus_id
      and bra.route_id = dt.route_id
      and bra.route_trip_pattern_id = dt.route_trip_pattern_id
    where dt.tenant_id = v_tenant_id and dt.status = 'active'
  ) then
    raise exception 'End the active bus run before ending this route service.'
      using errcode = '55006';
  end if;

  update public.driver_route_assignments
  set status = 'inactive'
  where bus_route_assignment_id = any(v_ids)
    and tenant_id = v_tenant_id
    and status = 'active';
  get diagnostics v_driver_count = row_count;

  update public.student_bus_assignments
  set status = 'inactive',
      effective_to = case
        when effective_from > current_date then effective_from
        when effective_to is null or effective_to > current_date then current_date
        else effective_to
      end
  where bus_route_assignment_id = any(v_ids)
    and tenant_id = v_tenant_id
    and status = 'active';
  get diagnostics v_student_count = row_count;

  update public.bus_route_assignments
  set status = 'inactive',
      effective_to = case
        when effective_from > current_date then effective_from
        when effective_to is null or effective_to > current_date then current_date
        else effective_to
      end
  where id = any(v_ids) and tenant_id = v_tenant_id and status = 'active';

  return jsonb_build_object(
    'busRouteAssignmentIds', to_jsonb(v_ids),
    'driverAssignmentsEnded', v_driver_count,
    'studentAssignmentsEnded', v_student_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_student_bus_service_status(p_assignment_ids uuid[], p_status text, p_end_service boolean DEFAULT false)
 RETURNS SETOF student_bus_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_ids uuid[] := coalesce(p_assignment_ids, array[]::uuid[]);
begin
  if auth.uid() is null
    or v_tenant_id is null
    or not safebus_private.is_transportation_write_admin() then
    raise exception 'Admin tenant context is required.' using errcode = '42501';
  end if;
  if p_status not in ('active', 'inactive', 'archived') then
    raise exception 'Unsupported student service status.' using errcode = '22023';
  end if;
  if cardinality(v_ids) = 0
    or (select count(*) from public.student_bus_assignments sba
        where sba.id = any(v_ids) and sba.tenant_id = v_tenant_id) <> cardinality(v_ids) then
    raise exception 'Student service assignments were not found.' using errcode = 'P0002';
  end if;

  perform 1 from public.student_bus_assignments sba where sba.id = any(v_ids) for update;

  if p_status = 'active' and exists (
    select 1
    from public.student_bus_assignments sba
    join public.bus_route_assignments bra on bra.id = sba.bus_route_assignment_id
    where sba.id = any(v_ids)
      and (bra.status <> 'active'
        or (bra.effective_to is not null and bra.effective_to < current_date))
  ) then
    raise exception 'The bus route service is no longer active.' using errcode = '55006';
  end if;

  update public.student_bus_assignments
  set status = p_status,
      effective_to = case
        when not p_end_service then effective_to
        when effective_from > current_date then effective_from
        when effective_to is null or effective_to > current_date then current_date
        else effective_to
      end
  where id = any(v_ids) and tenant_id = v_tenant_id;

  return query
  select sba.* from public.student_bus_assignments sba
  where sba.id = any(v_ids) and sba.tenant_id = v_tenant_id
  order by sba.route_trip_pattern_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_bus_qr_start_options(p_qr_token text)
 RETURNS TABLE(bus_route_assignment_id uuid, bus_number text, route_code text, route_name text, trip_name text, direction text, resumed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_driver_id uuid := safebus_private.current_driver_id();
  v_hash text;
  v_bus public.buses;
  v_existing_trip public.driver_trips;
begin
  if auth.uid() is null or safebus_private.current_user_role() <> 'driver'
    or v_tenant_id is null or v_driver_id is null then
    raise exception 'Only an active driver can scan a bus.' using errcode = '42501';
  end if;
  if p_qr_token is null or p_qr_token !~ '^sbus_bus_v1_[A-Za-z0-9_-]{40,80}$' then
    raise exception 'Bus QR could not be verified.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.drivers d
    where d.id = v_driver_id and d.tenant_id = v_tenant_id and d.status = 'active'
  ) then
    raise exception 'An active driver identity is required.' using errcode = '42501';
  end if;

  v_hash := safebus_private.hash_bus_tracking_token(p_qr_token);
  select b.* into v_bus
  from public.bus_qr_credentials c
  join public.buses b on b.id = c.bus_id and b.tenant_id = c.tenant_id
  where c.token_hash = v_hash
    and c.status = 'active'
    and c.tenant_id = v_tenant_id
    and b.status = 'active';
  if not found then
    raise exception 'Bus QR could not be verified.' using errcode = 'P0002';
  end if;

  select dt.* into v_existing_trip
  from public.driver_trips dt
  where dt.driver_id = v_driver_id and dt.tenant_id = v_tenant_id and dt.status = 'active';
  if found and v_existing_trip.bus_id <> v_bus.id then
    raise exception 'End your active trip before scanning another bus.' using errcode = '55006';
  end if;

  return query
  select bra.id, v_bus.bus_number, r.route_code, r.route_name,
    rtp.display_name, rtp.direction, v_existing_trip.id is not null
  from public.bus_route_assignments bra
  join public.routes r
    on r.id = bra.route_id and r.tenant_id = bra.tenant_id
    and r.status = 'active' and r.definition_status = 'ready'
  join public.route_trip_patterns rtp
    on rtp.id = bra.route_trip_pattern_id and rtp.route_id = bra.route_id
    and rtp.tenant_id = bra.tenant_id and rtp.status = 'active'
    and not rtp.schedule_review_required
  where bra.tenant_id = v_tenant_id
    and bra.bus_id = v_bus.id
    and (
      (v_existing_trip.id is null
        and bra.status = 'active'
        and (bra.effective_from is null or bra.effective_from <= current_date)
        and (bra.effective_to is null or bra.effective_to >= current_date))
      or
      (v_existing_trip.id is not null
        and bra.route_id = v_existing_trip.route_id
        and bra.route_trip_pattern_id = v_existing_trip.route_trip_pattern_id)
    )
  order by r.route_code, rtp.direction;
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_bus(p_assignment_id uuid, p_replacement_bus_id uuid)
 RETURNS driver_route_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant uuid := safebus_private.current_tenant_id();
  v_orig public.driver_route_assignments;
  v_bus public.buses;
  v_new public.driver_route_assignments;
begin
  if auth.uid() is null or v_tenant is null
    or not safebus_private.is_transportation_write_admin() then
    raise exception 'Admin tenant context is required.' using errcode = '42501';
  end if;

  select * into v_orig from public.driver_route_assignments
  where id = p_assignment_id for update;
  if not found or v_orig.tenant_id is distinct from v_tenant then
    raise exception 'Assignment not found.' using errcode = 'P0002';
  end if;
  if not safebus_private.can_write_route_stop(v_orig.tenant_id, v_orig.route_id) then
    raise exception 'Assignment not found.' using errcode = 'P0002';
  end if;

  select * into v_bus from public.buses
  where id = p_replacement_bus_id and tenant_id = v_tenant and status = 'active'
  for update;
  if not found then
    raise exception 'Choose an active replacement bus in your organization.'
      using errcode = '23514';
  end if;
  if not safebus_private.can_write_optional_school(v_bus.tenant_id, v_bus.school_id) then
    raise exception 'Choose an active replacement bus in your organization.'
      using errcode = '23514';
  end if;
  if v_bus.id = v_orig.bus_id then
    raise exception 'The replacement must be a different bus.' using errcode = '22023';
  end if;

  if exists (
    select 1 from public.driver_trips dt
    where dt.driver_id = v_orig.driver_id
      and dt.tenant_id = v_tenant
      and dt.bus_id = v_orig.bus_id
      and dt.route_id = v_orig.route_id
      and dt.status in ('active', 'paused')
  ) then
    raise exception 'Complete or cancel the open trip before replacing the bus.'
      using errcode = '55006';
  end if;

  update public.driver_route_assignments
  set status = 'inactive'
  where id = v_orig.id;

  insert into public.driver_route_assignments (
    tenant_id, driver_id, bus_id, route_id, trip_type, status,
    effective_from, effective_to
  ) values (
    v_tenant, v_orig.driver_id, v_bus.id, v_orig.route_id, v_orig.trip_type,
    'active', coalesce(v_orig.effective_from, current_date), v_orig.effective_to
  )
  returning * into v_new;

  begin
    perform safebus_private.write_audit_event_legacy(
      'transportation.replace_bus', v_tenant, v_orig.id::text,
      'driver_route_assignment', 'success',
      jsonb_build_object(
        'original_bus_id', v_orig.bus_id::text,
        'replacement_bus_id', v_bus.id::text,
        'new_assignment_id', v_new.id::text
      )
    );
  exception when others then null;
  end;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_bus_tracking_from_qr(p_qr_token text, p_bus_route_assignment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_driver_id uuid := safebus_private.current_driver_id();
  v_hash text;
  v_credential public.bus_qr_credentials;
  v_bus public.buses;
  v_assignment public.bus_route_assignments;
  v_pattern public.route_trip_patterns;
  v_trip public.driver_trips;
  v_existing_trip public.driver_trips;
  v_session_token text;
  v_session_hash text;
begin
  if auth.uid() is null or safebus_private.current_user_role() <> 'driver'
    or v_tenant_id is null or v_driver_id is null then
    raise exception 'Only an active driver can scan a bus.' using errcode = '42501';
  end if;
  if p_qr_token is null or p_qr_token !~ '^sbus_bus_v1_[A-Za-z0-9_-]{40,80}$'
    or p_bus_route_assignment_id is null then
    raise exception 'Bus QR and route choice could not be verified.' using errcode = '22023';
  end if;

  perform 1 from public.drivers d
  where d.id = v_driver_id and d.tenant_id = v_tenant_id and d.status = 'active'
  for update;
  if not found then
    raise exception 'An active driver identity is required.' using errcode = '42501';
  end if;

  v_hash := safebus_private.hash_bus_tracking_token(p_qr_token);
  select c.* into v_credential
  from public.bus_qr_credentials c
  where c.token_hash = v_hash and c.status = 'active'
  for update;
  if not found or v_credential.tenant_id <> v_tenant_id then
    raise exception 'Bus QR could not be verified.' using errcode = 'P0002';
  end if;

  select b.* into v_bus
  from public.buses b
  where b.id = v_credential.bus_id and b.tenant_id = v_tenant_id and b.status = 'active'
  for update;
  if not found then
    raise exception 'This bus is not active.' using errcode = '55006';
  end if;

  select bra.* into v_assignment
  from public.bus_route_assignments bra
  join public.routes r
    on r.id = bra.route_id and r.tenant_id = bra.tenant_id
    and r.status = 'active' and r.definition_status = 'ready'
  join public.route_trip_patterns rtp
    on rtp.id = bra.route_trip_pattern_id and rtp.route_id = bra.route_id
    and rtp.tenant_id = bra.tenant_id and rtp.status = 'active'
    and not rtp.schedule_review_required
  where bra.id = p_bus_route_assignment_id
    and bra.bus_id = v_bus.id
    and bra.tenant_id = v_tenant_id
  for update of bra;
  if not found then
    raise exception 'The selected route direction is not assigned to this bus.' using errcode = 'P0002';
  end if;

  select rtp.* into v_pattern
  from public.route_trip_patterns rtp
  where rtp.id = v_assignment.route_trip_pattern_id
    and rtp.tenant_id = v_tenant_id;

  select dt.* into v_existing_trip
  from public.driver_trips dt
  where dt.driver_id = v_driver_id and dt.tenant_id = v_tenant_id and dt.status = 'active'
  for update;

  if found then
    if v_existing_trip.bus_id <> v_bus.id then
      raise exception 'End your active trip before scanning another bus.' using errcode = '55006';
    end if;
    if v_existing_trip.route_id <> v_assignment.route_id
      or v_existing_trip.route_trip_pattern_id <> v_assignment.route_trip_pattern_id then
      raise exception 'The active bus run direction cannot be changed while resuming.'
        using errcode = '55006';
    end if;
    v_trip := v_existing_trip;
  else
    if v_assignment.status <> 'active'
      or (v_assignment.effective_from is not null and v_assignment.effective_from > current_date)
      or (v_assignment.effective_to is not null and v_assignment.effective_to < current_date) then
      raise exception 'The selected route direction is not active today.' using errcode = '55006';
    end if;
    if exists (
      select 1 from public.driver_trips dt
      where dt.bus_id = v_bus.id and dt.tenant_id = v_tenant_id and dt.status = 'active'
    ) then
      raise exception 'This bus already has an active trip.' using errcode = '55006';
    end if;

    begin
      insert into public.driver_trips (
        tenant_id, driver_id, bus_id, route_id, route_trip_pattern_id,
        driver_route_assignment_id, route_shape_id, bus_number_snapshot,
        trip_name_snapshot, trip_type, status, service_date, started_at
      ) values (
        v_tenant_id, v_driver_id, v_bus.id, v_assignment.route_id,
        v_assignment.route_trip_pattern_id, null,
        safebus_private.current_route_shape_id_for_route(v_assignment.route_id, v_tenant_id),
        v_bus.bus_number, v_pattern.display_name,
        case when v_pattern.direction = 'reverse' then 'evening' else 'morning' end,
        'active', current_date, now()
      ) returning * into v_trip;
    exception when unique_violation then
      raise exception 'This driver or bus already has an active trip.' using errcode = '55006';
    end;
  end if;

  update public.bus_tracking_sessions
  set status = 'revoked', ended_at = now()
  where status = 'active'
    and (driver_trip_id = v_trip.id or driver_id = v_driver_id or bus_id = v_bus.id);

  loop
    v_session_token := safebus_private.create_bus_tracking_session_token();
    v_session_hash := safebus_private.hash_bus_tracking_token(v_session_token);
    exit when not exists (
      select 1 from public.bus_tracking_sessions where session_token_hash = v_session_hash
    );
  end loop;

  insert into public.bus_tracking_sessions (
    tenant_id, driver_trip_id, driver_id, bus_id, bus_qr_credential_id,
    session_token_hash
  ) values (
    v_tenant_id, v_trip.id, v_driver_id, v_bus.id, v_credential.id,
    v_session_hash
  );

  return jsonb_build_object(
    'trip', to_jsonb(v_trip),
    'trackingToken', v_session_token,
    'busNumber', v_bus.bus_number,
    'resumed', v_existing_trip.id is not null
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.substitute_driver(p_assignment_id uuid, p_substitute_driver_id uuid)
 RETURNS driver_route_assignments
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant uuid := safebus_private.current_tenant_id();
  v_orig public.driver_route_assignments;
  v_sub public.drivers;
  v_new public.driver_route_assignments;
begin
  if auth.uid() is null or v_tenant is null
    or not safebus_private.is_transportation_write_admin() then
    raise exception 'Admin tenant context is required.' using errcode = '42501';
  end if;

  select * into v_orig from public.driver_route_assignments
  where id = p_assignment_id for update;
  if not found or v_orig.tenant_id is distinct from v_tenant then
    raise exception 'Assignment not found.' using errcode = 'P0002';
  end if;
  if not safebus_private.can_write_route_stop(v_orig.tenant_id, v_orig.route_id) then
    raise exception 'Assignment not found.' using errcode = 'P0002';
  end if;

  select * into v_sub from public.drivers
  where id = p_substitute_driver_id and tenant_id = v_tenant and status = 'active'
  for update;
  if not found then
    raise exception 'Choose an active substitute driver in your organization.'
      using errcode = '23514';
  end if;
  if not safebus_private.can_write_driver_profile(v_sub.tenant_id, v_sub.profile_id) then
    raise exception 'Choose an active substitute driver in your organization.'
      using errcode = '23514';
  end if;
  if v_sub.id = v_orig.driver_id then
    raise exception 'The substitute must be a different driver.'
      using errcode = '22023';
  end if;

  if exists (
    select 1 from public.driver_trips dt
    where dt.driver_id = v_orig.driver_id
      and dt.tenant_id = v_tenant
      and dt.bus_id = v_orig.bus_id
      and dt.route_id = v_orig.route_id
      and dt.status in ('active', 'paused')
  ) then
    raise exception 'Complete or cancel the open trip before substituting the driver.'
      using errcode = '55006';
  end if;

  update public.driver_route_assignments
  set status = 'inactive'
  where id = v_orig.id;

  insert into public.driver_route_assignments (
    tenant_id, driver_id, bus_id, route_id, trip_type, status,
    effective_from, effective_to
  ) values (
    v_tenant, v_sub.id, v_orig.bus_id, v_orig.route_id, v_orig.trip_type,
    'active', coalesce(v_orig.effective_from, current_date), v_orig.effective_to
  )
  returning * into v_new;

  begin
    perform safebus_private.write_audit_event_legacy(
      'transportation.substitute_driver', v_tenant, v_orig.id::text,
      'driver_route_assignment', 'success',
      jsonb_build_object(
        'original_driver_id', v_orig.driver_id::text,
        'substitute_driver_id', v_sub.id::text,
        'new_assignment_id', v_new.id::text
      )
    );
  exception when others then null;
  end;

  return v_new;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.admin_create_student_onboarding_base(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_student_id uuid;
  v_school_id uuid;
  v_guardian_id uuid;
  v_guardian_link_id uuid;
  v_route_id uuid;
  v_bus_id uuid;
  v_service_id uuid;
  v_pickup_stop_id uuid;
  v_dropoff_stop_id uuid;
  v_assignment_id uuid;
  v_first_name text := btrim(coalesce(p_payload #>> '{student,firstName}', ''));
  v_last_name text := btrim(coalesce(p_payload #>> '{student,lastName}', ''));
  v_preferred_name text := nullif(btrim(coalesce(p_payload #>> '{student,preferredName}', '')), '');
  v_grade text := nullif(btrim(coalesce(p_payload #>> '{student,grade}', '')), '');
  v_school_student_number text := nullif(btrim(coalesce(p_payload #>> '{student,schoolStudentNumber}', '')), '');
  v_relationship text := coalesce(nullif(btrim(p_payload #>> '{guardian,relationship}'), ''), 'guardian');
  v_transportation_enabled boolean := coalesce((p_payload #>> '{transportation,enabled}')::boolean, false);
  v_route_name text;
  v_route_code text;
  v_route_type text;
  v_bus_number text;
  v_license_plate text;
  v_capacity integer;
  v_trip_type text;
  v_effective_from date;
  v_stop_order integer;
  v_pickup_mode text;
  v_dropoff_mode text;
  v_new_stop_name text;
  v_new_stop_time time;
  v_link public.student_guardians;
begin
  if auth.uid() is null or v_tenant_id is null then
    raise exception 'Authentication and tenant context are required.' using errcode = '42501';
  end if;

  if safebus_private.current_user_role() <> 'tenant_admin' then
    raise exception 'Only a tenant administrator can use student onboarding.' using errcode = '42501';
  end if;

  if p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or octet_length(p_payload::text) > 32768 then
    raise exception 'Invalid student onboarding payload.' using errcode = '22023';
  end if;

  if v_first_name = '' or v_last_name = '' then
    raise exception 'Student first name and last name are required.' using errcode = '22023';
  end if;

  if length(v_first_name) > 100
     or length(v_last_name) > 100
     or length(coalesce(v_preferred_name, '')) > 100
     or length(coalesce(v_grade, '')) > 40
     or length(coalesce(v_school_student_number, '')) > 100 then
    raise exception 'One or more student fields are too long.' using errcode = '22023';
  end if;

  v_school_id := nullif(p_payload #>> '{student,schoolId}', '')::uuid;
  if v_school_id is not null and not exists (
    select 1
    from public.schools s
    where s.id = v_school_id
      and s.tenant_id = v_tenant_id
      and s.status = 'active'
  ) then
    raise exception 'School not found in your tenant.' using errcode = 'P0002';
  end if;

  v_guardian_id := nullif(p_payload #>> '{guardian,id}', '')::uuid;
  if v_guardian_id is not null then
    if v_relationship not in ('mother', 'father', 'guardian', 'caregiver', 'other') then
      raise exception 'Invalid guardian relationship.' using errcode = '22023';
    end if;
    if not exists (
      select 1
      from public.guardians g
      join public.profiles p
        on p.id = g.profile_id
       and p.tenant_id = g.tenant_id
       and p.role = 'guardian'
      where g.id = v_guardian_id
        and g.tenant_id = v_tenant_id
        and g.status = 'active'
        and p.status in ('invited', 'active')
    ) then
      raise exception 'Guardian not found in your tenant.' using errcode = 'P0002';
    end if;
  end if;

  insert into public.students (
    tenant_id,
    school_id,
    first_name,
    last_name,
    preferred_name,
    grade,
    school_student_number,
    status
  )
  values (
    v_tenant_id,
    v_school_id,
    v_first_name,
    v_last_name,
    v_preferred_name,
    v_grade,
    v_school_student_number,
    'active'
  )
  returning id into v_student_id;

  if v_guardian_id is not null then
    select * into v_link
    from public.admin_link_student_guardian(
      v_student_id,
      v_guardian_id,
      v_relationship,
      true
    );
    v_guardian_link_id := v_link.id;
  end if;

  if v_transportation_enabled then
    v_route_id := nullif(p_payload #>> '{transportation,route,id}', '')::uuid;
    if v_route_id is null then
      v_route_name := btrim(coalesce(p_payload #>> '{transportation,route,name}', ''));
      v_route_code := btrim(coalesce(p_payload #>> '{transportation,route,code}', ''));
      v_route_type := coalesce(nullif(btrim(p_payload #>> '{transportation,route,type}'), ''), 'morning');
      if v_route_name = '' or v_route_code = '' then
        raise exception 'Route name and code are required for a new route.' using errcode = '22023';
      end if;
      if length(v_route_name) > 160 or length(v_route_code) > 40 then
        raise exception 'Route name or code is too long.' using errcode = '22023';
      end if;
      if v_route_type not in ('morning', 'afternoon', 'special', 'field_trip') then
        raise exception 'Invalid route type.' using errcode = '22023';
      end if;
      insert into public.routes (
        tenant_id, school_id, route_name, route_code, route_type, status
      )
      values (
        v_tenant_id, v_school_id, v_route_name, v_route_code, v_route_type, 'active'
      )
      returning id into v_route_id;
    elsif not exists (
      select 1
      from public.routes r
      where r.id = v_route_id
        and r.tenant_id = v_tenant_id
        and r.status = 'active'
    ) then
      raise exception 'Route not found in your tenant.' using errcode = 'P0002';
    end if;

    v_bus_id := nullif(p_payload #>> '{transportation,bus,id}', '')::uuid;
    if v_bus_id is null then
      v_bus_number := btrim(coalesce(p_payload #>> '{transportation,bus,number}', ''));
      v_license_plate := nullif(btrim(coalesce(p_payload #>> '{transportation,bus,licensePlate}', '')), '');
      v_capacity := nullif(p_payload #>> '{transportation,bus,capacity}', '')::integer;
      if v_bus_number = '' then
        raise exception 'Bus number is required for a new bus.' using errcode = '22023';
      end if;
      if length(v_bus_number) > 40 or length(coalesce(v_license_plate, '')) > 40 then
        raise exception 'Bus number or license plate is too long.' using errcode = '22023';
      end if;
      if v_capacity is not null and (v_capacity < 0 or v_capacity > 200) then
        raise exception 'Bus capacity must be between 0 and 200.' using errcode = '22023';
      end if;
      insert into public.buses (
        tenant_id, school_id, bus_number, license_plate, capacity, status
      )
      values (
        v_tenant_id, v_school_id, v_bus_number, v_license_plate, v_capacity, 'active'
      )
      returning id into v_bus_id;
    elsif not exists (
      select 1
      from public.buses b
      where b.id = v_bus_id
        and b.tenant_id = v_tenant_id
        and b.status = 'active'
    ) then
      raise exception 'Bus not found in your tenant.' using errcode = 'P0002';
    end if;

    v_pickup_mode := coalesce(nullif(p_payload #>> '{transportation,pickupStop,mode}', ''), 'none');
    v_dropoff_mode := coalesce(nullif(p_payload #>> '{transportation,dropoffStop,mode}', ''), 'none');
    if v_pickup_mode not in ('none', 'existing', 'new')
       or v_dropoff_mode not in ('none', 'existing', 'new') then
      raise exception 'Invalid stop selection mode.' using errcode = '22023';
    end if;

    if v_pickup_mode = 'existing' then
      v_pickup_stop_id := nullif(p_payload #>> '{transportation,pickupStop,id}', '')::uuid;
      if v_pickup_stop_id is null or not exists (
        select 1
        from public.route_stops rs
        where rs.id = v_pickup_stop_id
          and rs.tenant_id = v_tenant_id
          and rs.route_id = v_route_id
          and rs.status = 'active'
      ) then
        raise exception 'Pickup stop not found on the selected route.' using errcode = 'P0002';
      end if;
    end if;

    if v_dropoff_mode = 'existing' then
      v_dropoff_stop_id := nullif(p_payload #>> '{transportation,dropoffStop,id}', '')::uuid;
      if v_dropoff_stop_id is null or not exists (
        select 1
        from public.route_stops rs
        where rs.id = v_dropoff_stop_id
          and rs.tenant_id = v_tenant_id
          and rs.route_id = v_route_id
          and rs.status = 'active'
      ) then
        raise exception 'Drop-off stop not found on the selected route.' using errcode = 'P0002';
      end if;
    end if;

    if v_pickup_mode = 'new' or v_dropoff_mode = 'new' then
      -- Serialize stop-order allocation for this route so concurrent
      -- onboarding requests cannot claim the same route stop order.
      perform pg_advisory_xact_lock(hashtextextended(v_route_id::text, 0));
    end if;

    if v_pickup_mode = 'new' then
      v_new_stop_name := btrim(coalesce(p_payload #>> '{transportation,pickupStop,name}', ''));
      v_new_stop_time := nullif(p_payload #>> '{transportation,pickupStop,plannedTime}', '')::time;
      if v_new_stop_name = '' or length(v_new_stop_name) > 160 then
        raise exception 'A valid pickup stop name is required.' using errcode = '22023';
      end if;
      select coalesce(max(rs.stop_order), 0) + 1
      into v_stop_order
      from public.route_stops rs
      where rs.route_id = v_route_id;
      insert into public.route_stops (
        tenant_id, route_id, school_id, stop_name, stop_order,
        planned_arrival_time, latitude, longitude, status
      )
      values (
        v_tenant_id, v_route_id, v_school_id, v_new_stop_name, v_stop_order,
        v_new_stop_time, null, null, 'active'
      )
      returning id into v_pickup_stop_id;
    end if;

    if v_dropoff_mode = 'new' then
      v_new_stop_name := btrim(coalesce(p_payload #>> '{transportation,dropoffStop,name}', ''));
      v_new_stop_time := nullif(p_payload #>> '{transportation,dropoffStop,plannedTime}', '')::time;
      if v_new_stop_name = '' or length(v_new_stop_name) > 160 then
        raise exception 'A valid drop-off stop name is required.' using errcode = '22023';
      end if;
      select coalesce(max(rs.stop_order), 0) + 1
      into v_stop_order
      from public.route_stops rs
      where rs.route_id = v_route_id;
      insert into public.route_stops (
        tenant_id, route_id, school_id, stop_name, stop_order,
        planned_arrival_time, latitude, longitude, status
      )
      values (
        v_tenant_id, v_route_id, v_school_id, v_new_stop_name, v_stop_order,
        v_new_stop_time, null, null, 'active'
      )
      returning id into v_dropoff_stop_id;
    end if;

    v_trip_type := coalesce(nullif(p_payload #>> '{transportation,tripType}', ''), 'morning');
    if v_trip_type not in ('morning', 'evening') then
      raise exception 'Invalid bus service trip type.' using errcode = '22023';
    end if;
    v_effective_from := coalesce(
      nullif(p_payload #>> '{transportation,effectiveFrom}', '')::date,
      current_date
    );

    insert into public.bus_route_assignments (
      tenant_id, bus_id, route_id, trip_type, effective_from, status
    )
    values (
      v_tenant_id, v_bus_id, v_route_id, v_trip_type, v_effective_from, 'active'
    )
    on conflict (tenant_id, bus_id, route_id, trip_type)
      where status = 'active'
    do update set updated_at = now()
    returning id into v_service_id;

    insert into public.student_bus_assignments (
      tenant_id,
      student_id,
      bus_route_assignment_id,
      pickup_stop_id,
      dropoff_stop_id,
      effective_from,
      status
    )
    values (
      v_tenant_id,
      v_student_id,
      v_service_id,
      v_pickup_stop_id,
      v_dropoff_stop_id,
      v_effective_from,
      'active'
    )
    returning id into v_assignment_id;
  end if;

  return jsonb_build_object(
    'studentId', v_student_id,
    'guardianLinkId', v_guardian_link_id,
    'routeId', v_route_id,
    'busId', v_bus_id,
    'busServiceId', v_service_id,
    'studentBusAssignmentId', v_assignment_id,
    'pickupStopId', v_pickup_stop_id,
    'dropoffStopId', v_dropoff_stop_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.prepare_bus_run(p_bus_route_assignment_id uuid)
 RETURNS bus_run_dispatches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_service public.bus_route_assignments;
  v_dispatch public.bus_run_dispatches;
begin
  if auth.uid() is null
    or v_tenant_id is null
    or not safebus_private.is_transportation_write_admin() then
    raise exception 'Preparing a bus run requires a tenant operational admin.'
      using errcode = '42501';
  end if;

  select bra.* into v_service
  from public.bus_route_assignments bra
  join public.buses b
    on b.id = bra.bus_id and b.tenant_id = bra.tenant_id and b.status = 'active'
  join public.routes r
    on r.id = bra.route_id and r.tenant_id = bra.tenant_id
    and r.status = 'active' and r.definition_status = 'ready'
  join public.route_trip_patterns rtp
    on rtp.id = bra.route_trip_pattern_id and rtp.route_id = bra.route_id
    and rtp.tenant_id = bra.tenant_id and rtp.status = 'active'
    and not rtp.schedule_review_required
  where bra.id = p_bus_route_assignment_id
    and bra.tenant_id = v_tenant_id
    and bra.status = 'active'
    and (bra.effective_from is null or bra.effective_from <= current_date)
    and (bra.effective_to is null or bra.effective_to >= current_date)
  for update of bra;

  if not found then
    raise exception 'This bus run is not ready today.' using errcode = '55006';
  end if;

  perform 1 from public.buses b where b.id = v_service.bus_id for update;
  if exists (
    select 1 from public.driver_trips dt
    where dt.bus_id = v_service.bus_id and dt.tenant_id = v_tenant_id and dt.status = 'active'
  ) then
    raise exception 'End the active trip before preparing another run.' using errcode = '55006';
  end if;

  update public.bus_run_dispatches
  set status = 'cancelled', cancelled_at = now()
  where tenant_id = v_tenant_id and bus_id = v_service.bus_id and status = 'ready';

  insert into public.bus_run_dispatches(
    tenant_id, bus_id, bus_route_assignment_id, route_id,
    route_trip_pattern_id, service_date, prepared_by
  ) values (
    v_service.tenant_id, v_service.bus_id, v_service.id, v_service.route_id,
    v_service.route_trip_pattern_id, current_date, auth.uid()
  ) returning * into v_dispatch;

  return v_dispatch;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.start_driver_trip_from_assignment(p_assignment_id uuid)
 RETURNS driver_trips
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_driver_id uuid := safebus_private.current_driver_id();
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_assignment public.driver_route_assignments;
  v_pattern public.route_trip_patterns;
  v_trip public.driver_trips;
begin
  if auth.uid() is null or safebus_private.current_user_role() <> 'driver' then raise exception 'Only a driver can start a trip.' using errcode = '42501'; end if;
  if v_driver_id is null or v_tenant_id is null then raise exception 'An active driver identity is required.' using errcode = '42501'; end if;
  if p_assignment_id is null then raise exception 'Assignment not found.' using errcode = 'P0002'; end if;
  perform 1 from public.drivers d where d.id = v_driver_id and d.tenant_id = v_tenant_id and d.status = 'active' for update;
  if not found then raise exception 'An active driver identity is required.' using errcode = '42501'; end if;
  if exists (select 1 from public.driver_trips dt where dt.driver_id = v_driver_id and dt.tenant_id = v_tenant_id and dt.status = 'active') then raise exception 'You already have an active trip. End it before starting another.' using errcode = '55006'; end if;
  select dra.* into v_assignment from public.driver_route_assignments dra where dra.id = p_assignment_id for update;
  if not found then raise exception 'Assignment not found.' using errcode = 'P0002'; end if;
  if v_assignment.tenant_id <> v_tenant_id or v_assignment.driver_id <> v_driver_id then raise exception 'This assignment does not belong to the current driver.' using errcode = '42501'; end if;
  if v_assignment.status <> 'active' or (v_assignment.effective_from is not null and v_assignment.effective_from > current_date) or (v_assignment.effective_to is not null and v_assignment.effective_to < current_date) then raise exception 'This assignment is not active today.' using errcode = '55006'; end if;
  perform 1 from public.buses b where b.id = v_assignment.bus_id and b.tenant_id = v_tenant_id and b.status = 'active' for update;
  if not found then raise exception 'The assigned bus is not active.' using errcode = '55006'; end if;
  if exists (select 1 from public.driver_trips dt where dt.bus_id = v_assignment.bus_id and dt.tenant_id = v_tenant_id and dt.status = 'active') then raise exception 'This bus already has an active trip. Choose another assignment or contact your transportation admin.' using errcode = '55006'; end if;
  select rtp.* into v_pattern
  from public.bus_route_assignments bra
  join public.routes r on r.id = bra.route_id and r.tenant_id = bra.tenant_id and r.status = 'active' and r.definition_status = 'ready'
  join public.route_trip_patterns rtp on rtp.id = bra.route_trip_pattern_id and rtp.route_id = bra.route_id and rtp.tenant_id = bra.tenant_id and rtp.status = 'active' and not rtp.schedule_review_required
  where bra.id = v_assignment.bus_route_assignment_id and bra.tenant_id = v_assignment.tenant_id and bra.bus_id = v_assignment.bus_id and bra.route_id = v_assignment.route_id and bra.route_trip_pattern_id = v_assignment.route_trip_pattern_id and bra.status = 'active' and (bra.effective_from is null or bra.effective_from <= current_date) and (bra.effective_to is null or bra.effective_to >= current_date);
  if not found then raise exception 'This assignment does not have an active bus service and trip pattern today.' using errcode = '55006'; end if;
  begin
    insert into public.driver_trips (tenant_id, driver_id, bus_id, route_id, route_trip_pattern_id, driver_route_assignment_id, route_shape_id, trip_name_snapshot, trip_type, status, service_date, started_at)
    values (v_assignment.tenant_id, v_assignment.driver_id, v_assignment.bus_id, v_assignment.route_id, v_pattern.id, v_assignment.id, safebus_private.current_route_shape_id_for_route(v_assignment.route_id, v_assignment.tenant_id), v_pattern.display_name, case when v_pattern.direction = 'reverse' then 'evening' else 'morning' end, 'active', current_date, now())
    returning * into v_trip;
  exception when unique_violation then raise exception 'A driver or bus active trip was created concurrently. Refresh and try again.' using errcode = '55006'; end;
  return v_trip;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.start_driver_trip_from_bus(p_bus_id uuid)
 RETURNS driver_trips
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'auth', 'extensions', 'realtime', 'pg_temp'
AS $function$
declare
  v_driver_id uuid := safebus_private.current_driver_id();
  v_tenant_id uuid := safebus_private.current_tenant_id();
  v_assignment public.driver_route_assignments;
  v_pattern public.route_trip_patterns;
  v_trip public.driver_trips;
  v_candidate_count integer;
  v_assignment_id uuid;
begin
  if auth.uid() is null or safebus_private.current_user_role() <> 'driver' then raise exception 'Only a driver can start a trip.' using errcode = '42501'; end if;
  if v_driver_id is null or v_tenant_id is null then raise exception 'An active driver identity is required.' using errcode = '42501'; end if;
  perform 1 from public.buses b where b.id = p_bus_id and b.tenant_id = v_tenant_id and b.status = 'active' for update;
  if not found then raise exception 'Assigned bus is not active.' using errcode = 'P0002'; end if;
  select count(*)::integer, min(dra.id::text)::uuid into v_candidate_count, v_assignment_id
  from public.driver_route_assignments dra
  join public.routes r on r.id = dra.route_id and r.tenant_id = dra.tenant_id and r.status = 'active'
  join public.route_trip_patterns rtp on rtp.id = dra.route_trip_pattern_id and rtp.route_id = dra.route_id and rtp.tenant_id = dra.tenant_id and rtp.status = 'active'
  where dra.tenant_id = v_tenant_id and dra.driver_id = v_driver_id and dra.bus_id = p_bus_id and dra.status = 'active' and (dra.effective_from is null or dra.effective_from <= current_date) and (dra.effective_to is null or dra.effective_to >= current_date);
  if v_candidate_count = 0 then raise exception 'No active assignment exists for this bus today.' using errcode = 'P0002'; end if;
  if v_candidate_count > 1 then raise exception 'This bus has multiple active route assignments today.' using errcode = '55006'; end if;
  select * into v_assignment from public.driver_route_assignments where id = v_assignment_id for update;
  select * into v_pattern from public.route_trip_patterns where id = v_assignment.route_trip_pattern_id;
  begin
    insert into public.driver_trips (tenant_id, driver_id, bus_id, route_id, route_trip_pattern_id, driver_route_assignment_id, route_shape_id, trip_name_snapshot, trip_type, status, service_date, started_at)
    values (v_tenant_id, v_driver_id, p_bus_id, v_assignment.route_id, v_pattern.id, v_assignment.id, safebus_private.current_route_shape_id_for_route(v_assignment.route_id, v_tenant_id), v_pattern.display_name, case when v_pattern.direction = 'reverse' then 'evening' else 'morning' end, 'active', current_date, now()) returning * into v_trip;
  exception when unique_violation then raise exception 'The driver or bus already has an active trip.' using errcode = '55006'; end;
  return v_trip;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.validate_bus_capacity_reservations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'pg_temp'
AS $function$
begin
  if new.capacity is null or new.capacity is not distinct from old.capacity then return new; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Seat and capacity changes require READ COMMITTED isolation.' using errcode = '0A000';
  end if;
  -- UPDATE already owns the bus row lock used by the assignment trigger.
  if exists (
    select 1 from public.student_bus_assignments sba
    join public.bus_route_assignments bra on bra.id = sba.bus_route_assignment_id and bra.tenant_id = sba.tenant_id
    where bra.bus_id = new.id and bra.tenant_id = new.tenant_id and bra.status = 'active'
      and (bra.effective_to is null or bra.effective_to >= current_date)
      and sba.status = 'active' and (sba.effective_to is null or sba.effective_to >= current_date)
      and sba.seat_number > new.capacity
  ) then
    raise exception 'Bus capacity cannot be lower than a currently or future reserved seat.'
      using errcode = '23514', constraint = 'bus_capacity_reserved_seat';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.validate_bus_service_seat_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'pg_temp'
AS $function$
declare v_capacity integer;
begin
  if new.status <> 'active' or (new.effective_to is not null and new.effective_to < current_date) then return new; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Seat and capacity changes require READ COMMITTED isolation.' using errcode = '0A000';
  end if;
  select b.capacity into v_capacity from public.buses b
    where b.id = new.bus_id and b.tenant_id = new.tenant_id for update;
  if exists (select 1 from public.student_bus_assignments sba
    where sba.bus_route_assignment_id = new.id and sba.status = 'active'
      and (sba.effective_to is null or sba.effective_to >= current_date) and sba.seat_number > v_capacity) then
    raise exception 'Seat number exceeds this bus capacity.'
      using errcode = '23514', constraint = 'student_seat_bus_capacity';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION safebus_private.validate_student_seat_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'safebus_private', 'pg_temp'
AS $function$
declare v_capacity integer; v_bus_id uuid; v_check boolean;
begin
  if new.seat_number is null then return new; end if;
  v_check := new.status = 'active' and (new.effective_to is null or new.effective_to >= current_date);
  if tg_op = 'INSERT' then v_check := true;
  elsif new.seat_number is distinct from old.seat_number
     or new.bus_route_assignment_id is distinct from old.bus_route_assignment_id then v_check := true;
  end if;
  if not v_check then return new; end if;
  if current_setting('transaction_isolation') <> 'read committed' then
    raise exception 'Seat and capacity changes require READ COMMITTED isolation.' using errcode = '0A000';
  end if;
  select bra.bus_id into v_bus_id from public.bus_route_assignments bra
    where bra.id = new.bus_route_assignment_id and bra.tenant_id = new.tenant_id for share;
  select b.capacity into v_capacity from public.buses b
    where b.id = v_bus_id and b.tenant_id = new.tenant_id for update;
  if not found then raise exception 'Bus service is not available.' using errcode = '23514'; end if;
  if v_capacity is not null and new.seat_number > v_capacity then
    raise exception 'Seat number exceeds this bus capacity.'
      using errcode = '23514', constraint = 'student_seat_bus_capacity';
  end if;
  return new;
end;
$function$
